import { useCallback } from 'react'
import { DisplayFlexCCC } from '../../../../../commonStyle/index.style'
import { CustomText } from '../../../../../components'
import ButtonWithIcon from '../../../../../components/ButtonWithIcon'
import { AgentColorPallette } from '../../../../../configs/colorPallete'
import { GENERAL_LOCK, UNAUTHORIZED_ACCESS_PEOPLE } from '../../../../../images'
import { UNAUTHORIZED_ACCESS_LANG } from '../../../../../lang'
import { useAgentLogout } from '../../../../../state/globalState/hooks/useGlobalContext'
import { UnauthorizedAccessStyle } from './index.style'

function UnauthorizedAccess (props) {
  const { history } = props
  const [, logoutAgentRequest] = useAgentLogout()

  const handleLogin = useCallback(() => {
    logoutAgentRequest()
    history.replace('/login')
  }, [history, logoutAgentRequest])

  return (
    <UnauthorizedAccessStyle>
      <DisplayFlexCCC className='unauthorized-img-container'>
        <img src={UNAUTHORIZED_ACCESS_PEOPLE} alt='Unauthorized access' />
      </DisplayFlexCCC>
      <CustomText
        color={AgentColorPallette.black}
        weight={800}
        size='16px'
        top='10px'
      >
        {UNAUTHORIZED_ACCESS_LANG.youCannotProcess}
      </CustomText>
      <CustomText
        color={AgentColorPallette.darkCharcoal}
        textAlign='center'
        top='8px'
      >
        {UNAUTHORIZED_ACCESS_LANG.youDonNotHaveAccessThePage}
      </CustomText>
      <div className='btn-container'>
        <ButtonWithIcon
          text={UNAUTHORIZED_ACCESS_LANG.login}
          icon={GENERAL_LOCK}
          iconRight
          onClick={handleLogin}
        />
      </div>
    </UnauthorizedAccessStyle>
  )
}

export default UnauthorizedAccess
