import { Container, CustomText } from '../../../../../../components'
import { LANG_STRINGS } from '../../../../../../lang'
import { UnderPaymentStyle } from './index.style'
import {
  Row,
  DisplayCircleIcon
} from '../../../../../../commonStyle/index.style'
import { AgentColorPallette } from '../../../../../../configs/colorPallete'
import { formatMoney } from '../../../../../../helpers/utility'
import CustomCheckbox from '../../../../../../components/CustomCheckbox'
import ButtonWithIcon from '../../../../../../components/ButtonWithIcon'
import { INFO, CHECK_GOLD } from '../../../../../../images'
import { useCallback, useEffect, useMemo, useRef, useState } from 'react'
import get from 'lodash/get'
import {
  useErrorContextValue,
  useLoaderContextValue,
  resetError
} from '@pasarpolis/common-react-hooks'
import {
  useGetProofSettlement,
  useSubmitProofSettlement,
  useToggleBonusBalance
} from '../../../state/hooks/useInstantPayout'
import { setToLocalStorage } from '../../../../../../helpers/localstorage'
import { PROOF_ID } from '../../../../../../constants/cookies'
import ShowSnackbar from '../../../../../../components/ShowNotification'
import UnauthorizedAccess from '../../../components/UnauthoriseAccess'

function UnderPaymentContainer (props) {
  const [
    { GET_PROOF_SETTLEMENT_LOADER, SUBMIT_PROOF_SETTLEMENT_LOADER }
  ] = useLoaderContextValue()
  const [settlementStatus, setSettlementStatus] = useState('')
  const [
    {
      GET_PROOF_SETTLEMENT_ERROR,
      getProofSettlementStatus,
      SUBMIT_PROOF_SETTLEMENT_ERROR,
      submitProofSettlementStatus
    },
    dispatchError
  ] = useErrorContextValue()
  const [isUseBonusBalance, setIsUseBonusBalance] = useState(false)

  const [
    { getProofSettlementData = {} },
    getProofSettlementRequest
  ] = useGetProofSettlement()

  const isPaymentByCustomer = useMemo(() => {
    return get(getProofSettlementData, 'payment_by', '') === 'CUSTOMER'
  }, [getProofSettlementData])

  // const isEndorsement = useMemo(() => {
  //   return get(getProofSettlementData, 'payment_for', '') === 'FOR_ENDORSEMENT'
  // }, [getProofSettlementData])

  const [, submitProofSettlementRequest] = useSubmitProofSettlement()
  const [, toggleBonusBalance] = useToggleBonusBalance()

  const proofId = useMemo(() => {
    return get(props, 'match.params.proofId', '')
  }, [props])
  const { history } = props
  const that = useRef({ isGetSettlementCall: false })

  const handlePhotoUpload = useCallback(() => {
    history.goBack()
  }, [history])

  const [showBar, setShowBar] = useState(null)
  const [barMsg, setBarMsg] = useState('')
  const [isBarMsgError, setIsBarMsgError] = useState(true)

  const handleShowSnackbar = (isShow, text, isError = true) => {
    setShowBar(isShow)
    setBarMsg(text)
    setIsBarMsgError(isError)
    setTimeout(() => {
      setShowBar(false)
    }, 4000)
  }

  useEffect(() => {
    return () => {
      setToLocalStorage(PROOF_ID, proofId)
    }
  }, [proofId])

  const handleApproveDifference = useCallback(() => {
    submitProofSettlementRequest({
      proofId: proofId,
      body: {
        ...getProofSettlementData
      }
    })
  }, [proofId, submitProofSettlementRequest, getProofSettlementData])

  const handleBonusBalanceChange = useCallback(() => {
    setIsUseBonusBalance(!isUseBonusBalance)
    if (!isUseBonusBalance) {
      getProofSettlementRequest({ proofId })
    } else {
      toggleBonusBalance(!isUseBonusBalance)
    }
  }, [
    isUseBonusBalance,
    setIsUseBonusBalance,
    toggleBonusBalance,
    proofId,
    getProofSettlementRequest
  ])

  useEffect(() => {
    const resetSubmitProofStatus = () => {
      dispatchError(
        resetError({
          submitProofSettlementStatus: ''
        })
      )
    }
    if (submitProofSettlementStatus === 'success') {
      history.replace({
        pathname: '/instant/payout/confirmation'
      })
      resetSubmitProofStatus()
    } else if (SUBMIT_PROOF_SETTLEMENT_ERROR && submitProofSettlementStatus) {
      handleShowSnackbar(true, submitProofSettlementStatus)
      resetSubmitProofStatus()
    }
  }, [
    submitProofSettlementStatus,
    SUBMIT_PROOF_SETTLEMENT_ERROR,
    dispatchError,
    history
  ])

  useEffect(() => {
    if (!that.current.isGetSettlementCall) {
      getProofSettlementRequest({ proofId })
      that.current.isGetSettlementCall = true
    }
  }, [getProofSettlementRequest, proofId])

  useEffect(() => {
    if (
      GET_PROOF_SETTLEMENT_ERROR &&
      getProofSettlementStatus &&
      getProofSettlementStatus !== 'success'
    ) {
      handleShowSnackbar(true, getProofSettlementStatus)
      dispatchError(
        resetError({
          getProofSettlementStatus: ''
        })
      )
      setSettlementStatus(getProofSettlementStatus)
    }
  }, [GET_PROOF_SETTLEMENT_ERROR, getProofSettlementStatus, dispatchError])

  const renderSection1 = useCallback(() => {
    const { total_premium: totalPremium } = getProofSettlementData
    return (
      <Row justify='space-between' className='section margin-bottom-5'>
        <CustomText
          fontSize='15px'
          color={AgentColorPallette.regular}
          weight={700}
        >
          {LANG_STRINGS.amountToBePaid}
        </CustomText>
        <CustomText
          fontSize='15px'
          color={AgentColorPallette.regular}
          weight={700}
        >
          {formatMoney(totalPremium)}
        </CustomText>
      </Row>
    )
  }, [getProofSettlementData])

  const amountRow = useCallback((label, labelDesc, amount, labelDescClass = '') => {
    return (
      <Row justify='space-between' className='amount-row'>
        <div>
          <CustomText fontSize='13px' color={AgentColorPallette.regular}>
            {label}
          </CustomText>
          {labelDesc && (
            <CustomText
              fontSize='10px'
              color={AgentColorPallette.fontDarkerGrey}
              className={labelDescClass}
            >
              {labelDesc}
            </CustomText>
          )}
        </div>
        <CustomText fontSize='13px' color={AgentColorPallette.regular}>
          {formatMoney(amount)}
        </CustomText>
      </Row>
    )
  }, [])

  const renderSection2 = useCallback(() => {
    const {
      offline_amount_payed: offlineAmountPayed,
      policy_commission: policyCommission,
      policy_commission_tax: policyCommissionTax,
      points,
      commission,
      commission_tax: commissionTax,
      policy_commission_used: policyCommissionUsed,
      commission_used: commissionUsed,
      points_used: pointsUsed,
      points_tax: pointsTax
    } = getProofSettlementData

    return (
      <div className='section margin-bottom-5'>
        <CustomText
          fontSize='15px'
          color={AgentColorPallette.regular}
          weight={700}
          className='border-bottom'
        >
          {LANG_STRINGS.payment}
        </CustomText>
        <Row className='border-bottom'>
          <CustomCheckbox color={AgentColorPallette.black} isChecked disabled />
          <div className='width-100'>
            <CustomText
              fontSize='13px'
              color={AgentColorPallette.regular}
              weight={800}
            >
              {LANG_STRINGS.offline}
            </CustomText>
            <CustomText
              fontSize='10px'
              color={AgentColorPallette.fontDarkerGrey}
            >
              {LANG_STRINGS.usingPaymentProof}
            </CustomText>
            {amountRow(LANG_STRINGS.paymentAmount, '', -offlineAmountPayed)}
          </div>
        </Row>

        {
          <Row>
            <CustomCheckbox
              color={AgentColorPallette.black}
              isChecked={isUseBonusBalance}
              onChange={handleBonusBalanceChange}
              disabled
            />
            <div className='width-100'>
              {['CUSTOMER', 'FOR_ENDORSEMENT', 'AGENT'].includes(getProofSettlementData?.payment_by) && (
                <div>
                  <CustomText
                    fontSize='13px'
                    color={AgentColorPallette.fontDarkerGrey}
                    weight={700}
                  >
                    {LANG_STRINGS.useBonus}
                  </CustomText>
                  <CustomText
                    fontSize='10px'
                    color={AgentColorPallette.fontDarkerGrey}
                  >
                    {formatMoney(policyCommission)}
                  </CustomText>
                  {amountRow(
                    LANG_STRINGS.bonusUsed,
                    `${LANG_STRINGS.afterTaxes} ${formatMoney(
                      policyCommissionUsed + policyCommissionTax
                    )}.`,
                    -policyCommissionUsed,
                    'border-bottom'
                  )}
                </div>
              )}
              <div>
                <CustomText
                  fontSize='13px'
                  color={AgentColorPallette.fontDarkerGrey}
                  weight={700}
                >
                  {LANG_STRINGS.useBalance}
                </CustomText>
                <CustomText
                  fontSize='10px'
                  color={AgentColorPallette.fontDarkerGrey}
                >
                  {LANG_STRINGS.commission}&nbsp;
                  {formatMoney(commission)}
                  &nbsp;&nbsp;&bull; {LANG_STRINGS.pointsSmall} &nbsp;
                  {points}
                </CustomText>
                {amountRow(
                  LANG_STRINGS.commissionUsed,
                  `${LANG_STRINGS.afterTaxes} ${formatMoney(
                    commissionUsed + commissionTax
                  )}`,
                  -commissionUsed
                )}
                {amountRow(
                  LANG_STRINGS.pointsUsed,
                  `${LANG_STRINGS.afterTaxes} ${formatMoney(
                    pointsUsed + pointsTax
                  )}.`,
                  -pointsUsed
                )}
              </div>
            </div>
          </Row>
        }
      </div>
    )
  }, [
    amountRow, getProofSettlementData, isUseBonusBalance,
    handleBonusBalanceChange
  ])

  const renderSection3 = useCallback(() => {
    const {
      commission_used: commissionUsed,
      remaining_payment: remainingPayment,
      total_tax: totalTax
    } = getProofSettlementData
    return (
      <div className='section margin-bottom-8'>
        {totalTax > 0 && (
          <div className='border-bottom'>
            {amountRow(
              LANG_STRINGS.incomeTax,
              LANG_STRINGS.takenFromBunus,
              totalTax
            )}
          </div>
        )}
        <Row justify='space-between'>
          <CustomText
            fontSize='15px'
            weight={800}
            color={
              remainingPayment === 0
                ? AgentColorPallette.regular
                : AgentColorPallette.maroonRed
            }
          >
            {LANG_STRINGS.finalDifference}
          </CustomText>
          <CustomText
            fontSize='15px'
            weight={800}
            color={
              remainingPayment === 0
                ? AgentColorPallette.regular
                : AgentColorPallette.maroonRed
            }
          >
            {formatMoney(
              remainingPayment < 0 ? -remainingPayment : remainingPayment
            )}
          </CustomText>
        </Row>

        {remainingPayment === 0 && (
          <ButtonWithIcon
            icon={CHECK_GOLD}
            iconRight
            className='approve-btn'
            onClick={handleApproveDifference}
            text={LANG_STRINGS.approveDifferencePayment}
          />
        )}
        {
          !(remainingPayment === 0 && !isPaymentByCustomer) && !(commissionUsed > 0 && remainingPayment === 0) && (
            <Row justify='space-around' className='info-container'>
              <DisplayCircleIcon
                width='18px'
                height='18px'
                bgColor={AgentColorPallette.black}
              >
                <img src={INFO} alt='INFO' className='info-img' />
              </DisplayCircleIcon>
              <CustomText
                color={AgentColorPallette.regular}
                fontSize='13px'
                className='width-90'
              >
                {remainingPayment === 0 ? (
                  LANG_STRINGS.remainingBonusWillBeCreditedToAccount
                ) : (
                  <span>
                    {LANG_STRINGS.underpaymentDifference}
                    <br />
                    <br />
                    {LANG_STRINGS.overpaymentDiffWillBeCreditedToAccount}.
                  </span>
                )}
              </CustomText>
            </Row>
          )
        }
      </div>
    )
  }, [amountRow, getProofSettlementData,
    handleApproveDifference, isPaymentByCustomer
  ])

  const renderSection4 = useCallback(() => {
    return (
      <div className='section-4'>
        <Row
          justify='space-between'
          className='border-bottom margin-0 border-top padding-lr'
          onClick={handlePhotoUpload}
        >
          <CustomText
            fontSize='13px'
            color={AgentColorPallette.uiGold}
            weight={800}
          >
            {LANG_STRINGS.uploadNewPhoto}
          </CustomText>
          <CustomText
            fontSize='13px'
            color={AgentColorPallette.uiGold}
            weight={800}
          >
            <i className='fas fa-angle-right' />
          </CustomText>
        </Row>
      </div>
    )
  }, [handlePhotoUpload])

  return (
    <Container
      title={LANG_STRINGS.differenceCalculation}
      hideBottomTabs
      loader={GET_PROOF_SETTLEMENT_LOADER || SUBMIT_PROOF_SETTLEMENT_LOADER}
    >
      {
        (GET_PROOF_SETTLEMENT_ERROR === false) && (
          <UnderPaymentStyle>
            {renderSection1()}
            {renderSection2()}
            {renderSection3()}
            {renderSection4()}
            {
              showBar && (<ShowSnackbar show={showBar} text={barMsg} error={isBarMsgError} />)
            }
          </UnderPaymentStyle>
        )
      }
      {
        GET_PROOF_SETTLEMENT_ERROR && (settlementStatus === 'Unauthorize Access') && (
          <UnauthorizedAccess history={history} />
        )
      }
    </Container>
  )
}

export default UnderPaymentContainer
